uint16_t amiga_os_name_id(uint8_t domain_kind, const char *name) {
  switch (domain_kind) {
  case 1u: return platform_name_id_from_table(g_amiga_os_library_names, (sizeof(g_amiga_os_library_names) / sizeof(g_amiga_os_library_names[0])), name);
  case 2u: return platform_name_id_from_table(g_amiga_os_base_names, (sizeof(g_amiga_os_base_names) / sizeof(g_amiga_os_base_names[0])), name);
  case 3u: return platform_name_id_from_table(g_amiga_os_function_names, (sizeof(g_amiga_os_function_names) / sizeof(g_amiga_os_function_names[0])), name);
  case 4u: return platform_name_id_from_table(g_amiga_os_symbol_names, (sizeof(g_amiga_os_symbol_names) / sizeof(g_amiga_os_symbol_names[0])), name);
  case 5u: return platform_name_id_from_table(g_amiga_os_include_names, (sizeof(g_amiga_os_include_names) / sizeof(g_amiga_os_include_names[0])), name);
  case 6u: return platform_name_id_from_table(g_amiga_os_type_names, (sizeof(g_amiga_os_type_names) / sizeof(g_amiga_os_type_names[0])), name);
  case 7u: return platform_name_id_from_table(g_amiga_os_struct_names, (sizeof(g_amiga_os_struct_names) / sizeof(g_amiga_os_struct_names[0])), name);
  case 8u: return platform_name_id_from_table(g_amiga_os_field_names, (sizeof(g_amiga_os_field_names) / sizeof(g_amiga_os_field_names[0])), name);
  case 9u: return platform_name_id_from_table(g_amiga_os_semantic_kind_names, (sizeof(g_amiga_os_semantic_kind_names) / sizeof(g_amiga_os_semantic_kind_names[0])), name);
  case 10u: return platform_name_id_from_table(g_amiga_os_value_domain_names, (sizeof(g_amiga_os_value_domain_names) / sizeof(g_amiga_os_value_domain_names[0])), name);
  default: return 0U;
  }
}

const char *amiga_os_name(uint8_t domain_kind, uint16_t id) {
  switch (domain_kind) {
  case 1u: return g_amiga_os_library_names[(size_t)id < (sizeof(g_amiga_os_library_names) / sizeof(g_amiga_os_library_names[0])) ? (size_t)id : (sizeof(g_amiga_os_library_names) / sizeof(g_amiga_os_library_names[0])) - 1U];
  case 2u: return g_amiga_os_base_names[(size_t)id < (sizeof(g_amiga_os_base_names) / sizeof(g_amiga_os_base_names[0])) ? (size_t)id : (sizeof(g_amiga_os_base_names) / sizeof(g_amiga_os_base_names[0])) - 1U];
  case 3u: return g_amiga_os_function_names[(size_t)id < (sizeof(g_amiga_os_function_names) / sizeof(g_amiga_os_function_names[0])) ? (size_t)id : (sizeof(g_amiga_os_function_names) / sizeof(g_amiga_os_function_names[0])) - 1U];
  case 4u: return g_amiga_os_symbol_names[(size_t)id < (sizeof(g_amiga_os_symbol_names) / sizeof(g_amiga_os_symbol_names[0])) ? (size_t)id : (sizeof(g_amiga_os_symbol_names) / sizeof(g_amiga_os_symbol_names[0])) - 1U];
  case 5u: return g_amiga_os_include_names[(size_t)id < (sizeof(g_amiga_os_include_names) / sizeof(g_amiga_os_include_names[0])) ? (size_t)id : (sizeof(g_amiga_os_include_names) / sizeof(g_amiga_os_include_names[0])) - 1U];
  case 6u: return g_amiga_os_type_names[(size_t)id < (sizeof(g_amiga_os_type_names) / sizeof(g_amiga_os_type_names[0])) ? (size_t)id : (sizeof(g_amiga_os_type_names) / sizeof(g_amiga_os_type_names[0])) - 1U];
  case 7u: return g_amiga_os_struct_names[(size_t)id < (sizeof(g_amiga_os_struct_names) / sizeof(g_amiga_os_struct_names[0])) ? (size_t)id : (sizeof(g_amiga_os_struct_names) / sizeof(g_amiga_os_struct_names[0])) - 1U];
  case 8u: return g_amiga_os_field_names[(size_t)id < (sizeof(g_amiga_os_field_names) / sizeof(g_amiga_os_field_names[0])) ? (size_t)id : (sizeof(g_amiga_os_field_names) / sizeof(g_amiga_os_field_names[0])) - 1U];
  case 9u: return g_amiga_os_semantic_kind_names[(size_t)id < (sizeof(g_amiga_os_semantic_kind_names) / sizeof(g_amiga_os_semantic_kind_names[0])) ? (size_t)id : (sizeof(g_amiga_os_semantic_kind_names) / sizeof(g_amiga_os_semantic_kind_names[0])) - 1U];
  case 10u: return g_amiga_os_value_domain_names[(size_t)id < (sizeof(g_amiga_os_value_domain_names) / sizeof(g_amiga_os_value_domain_names[0])) ? (size_t)id : (sizeof(g_amiga_os_value_domain_names) / sizeof(g_amiga_os_value_domain_names[0])) - 1U];
  default: return NULL;
  }
}

const char *amiga_os_register_name(uint8_t reg_kind, uint8_t reg_index) {
  static const char *const data_regs[] = { "D0", "D1", "D2", "D3", "D4", "D5", "D6", "D7" };
  static const char *const addr_regs[] = { "A0", "A1", "A2", "A3", "A4", "A5", "A6", "A7" };
  if (reg_index >= 8U) return NULL;
  if (reg_kind == AMIGA_OS_REGISTER_DATA) return data_regs[reg_index];
  if (reg_kind == AMIGA_OS_REGISTER_ADDRESS) return addr_regs[reg_index];
  return NULL;
}

